template<int N> inline CompositeChebyPoly getDepthPoly() {
    if constexpr (N == 4) return get_DepthPoly_4();
    else if constexpr (N == 8) return get_DepthPoly_8();
    else if constexpr (N == 16) return get_DepthPoly_16();
    else if constexpr (N == 32) return get_DepthPoly_32();
    else if constexpr (N == 64) return get_DepthPoly_64();
    else if constexpr (N == 128) return get_DepthPoly_128();
    else if constexpr (N == 256) return get_DepthPoly_256();
    else if constexpr (N == 512) return get_DepthPoly_512();
    else if constexpr (N == 1024) return get_DepthPoly_1024();
    else { static_assert(N >= 4 && N <= 1024); return get_DepthPoly_4(); }
}

template<int N> inline CompositeChebyPoly getMultPoly() {
    if constexpr (N == 4) return get_MultPoly_4();
    else if constexpr (N == 8) return get_MultPoly_8();
    else if constexpr (N == 16) return get_MultPoly_16();
    else if constexpr (N == 32) return get_MultPoly_32();
    else if constexpr (N == 64) return get_MultPoly_64();
    else if constexpr (N == 128) return get_MultPoly_128();
    else if constexpr (N == 256) return get_MultPoly_256();
    else if constexpr (N == 512) return get_MultPoly_512();
    else if constexpr (N == 1024) return get_MultPoly_1024();
    else { static_assert(N >= 4 && N <= 1024); return get_MultPoly_4(); }
}

inline CompositeChebyPoly getDepthPoly(int N) {
    switch (N) {
        case 4: return get_DepthPoly_4();
        case 8: return get_DepthPoly_8();
        case 16: return get_DepthPoly_16();
        case 32: return get_DepthPoly_32();
        case 64: return get_DepthPoly_64();
        case 128: return get_DepthPoly_128();
        case 256: return get_DepthPoly_256();
        case 512: return get_DepthPoly_512();
        case 1024: return get_DepthPoly_1024();
        default: throw std::runtime_error("Unsupported N");
    }
}

inline CompositeChebyPoly getMultPoly(int N) {
    switch (N) {
        case 4: return get_MultPoly_4();
        case 8: return get_MultPoly_8();
        case 16: return get_MultPoly_16();
        case 32: return get_MultPoly_32();
        case 64: return get_MultPoly_64();
        case 128: return get_MultPoly_128();
        case 256: return get_MultPoly_256();
        case 512: return get_MultPoly_512();
        case 1024: return get_MultPoly_1024();
        default: throw std::runtime_error("Unsupported N");
    }
}

